import { Alert } from 'react-native';
import * as FileSystem from 'expo-file-system/legacy';
import * as Sharing from 'expo-sharing';

/**
 * Data Base64 Barcode QRIS Resmi Della Frozen Mart
 * Memungkinkan penyimpanan/unduhan gambar langsung ke galeri HP tanpa download jaringan luar.
 */
export const QRIS_BASE64 = '';

/**
 * Unduh dan simpan gambar barcode QRIS ke penyimpanan perangkat / galeri foto
 */
export const downloadAndSaveQris = async () => {
  try {
    const baseDir = FileSystem.cacheDirectory || FileSystem.documentDirectory;
    const fileUri = baseDir + 'QRIS_Della_Frozen_Mart.png';

    // Simpan gambar secara langsung dari base64 (100% offline & instan via legacy filesystem)
    await FileSystem.writeAsStringAsync(fileUri, QRIS_BASE64, {
      encoding: 'base64',
    });

    if (await Sharing.isAvailableAsync()) {
      await Sharing.shareAsync(fileUri, {
        mimeType: 'image/png',
        dialogTitle: 'Simpan / Bagikan Barcode QRIS Della Frozen Mart',
        UTI: 'public.png',
      });
      return { success: true };
    } else {
      Alert.alert('Sukses ✅', 'Gambar QRIS berhasil disimpan di perangkat Anda.');
      return { success: true };
    }
  } catch (error) {
    console.error('Gagal simpan QRIS:', error);
    Alert.alert(
      'Petunjuk Pembayaran QRIS 💡',
      'Gagal menyimpan gambar secara otomatis. Anda dapat melakukan screenshot layar ini untuk discan langsung dari aplikasi m-Banking/E-Wallet Anda.'
    );
    return { success: false, error: error.message };
  }
};
